fn(f(x)) { return x + 1 }
s := 0

i := 0
while(i < 8000) { s += f(i); i += 1 }
print(s)

fn(f()) { return 1 }
s := 0

i := 0
while(i < 8000) { s += f(); i += 1 }
print(s)

fn(apply(f,x)) { return f(x) }
f := x => x + 1
s := 0

i := 0
while(i < 8000) { s += apply(f,i); i += 1 }
print(s)

adj := []
i := 0
while(i < 8000) { row := []; if(i+1 < 8000) { row.push(i+1) }; if(i+2 < 8000) { row.push(i+2) }; adj.push(row); i += 1 }
seen := set(); seen.add(0); q := [0]; qi := 0

while(qi < q.size()) { v := q[qi]; qi += 1; for(w : adj[v]) { if(!seen.contains(w)) { seen.add(w); q.push(w) } } }
print(seen.size())

